error.pattern:
//IfStat [ Expr::* / descendant::ExprCall
             [ Params[0]::ExprLiteral [ @Const = 'loggedIn' | @Const = 'loggedin' | @Const = 'logged' ] ]
         ]
         [ ThenStat::* /descendant ::ExprCall
             [ getQualifiedName() = 'javax.servlet.ServletRequest.getParameter' | getQualifiedName() = 'jakarta.servlet.ServletRequest.getParameter' ]
             [ Params[0]::ExprLiteral [ @Const = 'password' | @Const = 'Password' ] ]
         ]

//IfStat [ Expr::* /descendant::ExprCall
             [ Params[0]::ExprLiteral [ @Const = 'loggedIn' | @Const = 'loggedin' | @Const = 'logged' ] ]
         ]
         [ ThenStat::* /descendant ::ExprCall
             [ getQualifiedName() = 'javax.servlet.ServletRequest.getParameter' | getQualifiedName() = 'jakarta.servlet.ServletRequest.getParameter'  ]
             [ Params[0]::ExprLiteral [ @Const = 'userName' | @Const = 'username' ]
             [ $username := @Const ] ]
         ]

// ThrowExpr [not isCLanguage()] [ not ancestor::TryStmt ]
    [ ancestor::FuncDef [ isConstructor() ] / Declarator::FuncDeclarator [Params[0]::Decl [Declarators[*]::PtrDeclarator [@Spec=KTC_POINTEROPERATOR_RVALUE] ] ] [Params[1]::Null]
    | ancestor::MemberFunc [ isConstructor() ] / Declarator::FuncDeclarator [Params[0]::Decl [Declarators[*]::PtrDeclarator [@Spec=KTC_POINTEROPERATOR_RVALUE] ] ] [Params[1]::Null]
    ]

// Decl [not isCLanguage()]
        [ Declarators[*]::AnyDeclarator [ not isConst() ] [ isGlobal() ]
                                        [ isIncluded() ] [ isVariable() ]
                                        [ not isExtern() ] [ $0 := getName() ]
        ]

// BinaryExpr [ @Op = KTC_OPCODE_LT |
                @Op = KTC_OPCODE_GT |
                @Op = KTC_OPCODE_LE |
                @Op = KTC_OPCODE_GE ]
[ Left.getTypeName() = 'BSTR' |
Right.getTypeName() = 'BSTR' ]

// UnaryExpr [ @Op = KTC_OPCODE_PREINC |
               @Op = KTC_OPCODE_PREDEC |
               @Op = KTC_OPCODE_POSTINC |
               @Op = KTC_OPCODE_POSTDEC ]
             [ Expr.getTypeName() = 'BSTR' ]

// CallExpr [ getName() = 'SysReAllocString' | getName() = 'SysReAllocStringLen' ]
            [ $0 := getName() ]
            [ not Args[0]::* [ isPointerToBSTR() ] ]

// UnaryExpr [ @Op = KTC_OPCODE_PREINC |
               @Op = KTC_OPCODE_POSTINC |
               @Op = KTC_OPCODE_PREDEC |
               @Op = KTC_OPCODE_POSTDEC ]
             [ Expr.getTypeName() = 'bool' ]

// MemberDecl [ Declarators[*]::BitFieldDeclarator [ Bits::LiteralExpr [ getIntValue() = 1 ] ]
                                                   [ $0 := getName() ]
                                                   [ Declarator::AnyDeclarator.isSigned() ] ]

// BinaryExpr [ @Op = KTC_OPCODE_EQ | @Op = KTC_OPCODE_NE ]
              [ Left.getBaseIntegralTypeName() = 'char' ]
              [ Right:: { ParensExpr / Expr:: } AnyExpr [ pretty() = 'EOF' ] ]

// BinaryExpr [ @Op = KTC_OPCODE_ADD |
                @Op = KTC_OPCODE_ADDASSIGN |
                @Op = KTC_OPCODE_SUB |
                @Op = KTC_OPCODE_SUBASSIGN
              ]
              [ $ltype := Left.getLanguageType().getInitialDefinedType() ]
              [ $ltype.isPointer() ]
              [ $pltype := $ltype.getPointedType().getInitialDefinedType() ]
              [ $pltype.getTypeName() != 'void' ]
              [ $pltype.getTypeName() != 'char' ]
              [ Right::SizeOfExpr [ $sotype := Type.getSemanticInfo().getInitialDefinedType() ]
                                  [ $sotype.isPointer() | $sotype = $pltype ]
              ]
              [ $0 := Left.pretty() ]

// MemberExpr [ $className := getExpandedTypeName(getParent()) ] [ starts-with($className, 'std::') ] / parent::CallExpr [ getName() = 'empty' ]
              [ getTypeName(getReturnType()) = 'bool' ] [ $thisCall := this() ] [ parent::BinaryExpr [ @Op = KTC_OPCODE_COMMA ] [Right::CallExpr [ this() = $thisCall ] ]
              [ parent::ExprStmt | parent::BinaryExpr [ @Op = KTC_OPCODE_COMMA ] | parent::ForStmt [ Expr::BinaryExpr [Right::CallExpr [ this() = $thisCall ] ] ] ] ] [ $0 := $className ]

// BinaryExpr [ @Op=KTC_OPCODE_LT |
                @Op=KTC_OPCODE_GT |
                @Op=KTC_OPCODE_LE |
                @Op=KTC_OPCODE_GE |
                @Op=KTC_OPCODE_EQ |
                @Op=KTC_OPCODE_NE ]
              [ Left.getInitialDefinedType().getTypeName() = 'char' ]
              [ not Left::LiteralExpr ]
              [ not Right::LiteralExpr ]
              [ $right := Right.getInitialDefinedType().getTypeName() ]
              [ $right = 'signed char' | $right = 'unsigned char' ]

// BinaryExpr [ @Op=KTC_OPCODE_LT |
                @Op=KTC_OPCODE_GT |
                @Op=KTC_OPCODE_LE |
                @Op=KTC_OPCODE_GE |
                @Op=KTC_OPCODE_EQ |
                @Op=KTC_OPCODE_NE ]
              [ Right.getInitialDefinedType().getTypeName() = 'char']
              [ not Right::LiteralExpr ]
              [ not Left::LiteralExpr ]
              [ $left := Left.getInitialDefinedType().getTypeName() ]
              [ $left = 'signed char' | $left = 'unsigned char' ]

// CastExpr [ Type::TypeId [ $isok := getInitialDefinedType().isPointer() ] ]
            [ Expr::AnyExpr [ $isok != getInitialDefinedType().isPointer() ]
                            [ name() != 'LiteralExpr' | getIntValue() != 0 ] ]

//BinaryExpr [ not Left.isConstant() ]
             [ not Right.isConstant() ]
             [ @Op = KTC_OPCODE_BITAND | @Op = KTC_OPCODE_BITOR ]

// BinaryExpr [@Op = KTC_OPCODE_BITAND | @Op = KTC_OPCODE_BITOR | @Op = KTC_OPCODE_BITXOR]
              [not Left.isFromMacro()] [not Right.isFromMacro()]
              [ Left.isBoolean() | Right.isBoolean() ]

// BinaryExpr [@Op = KTC_OPCODE_LOGAND | @Op = KTC_OPCODE_LOGOR]
              [not Left.isFromMacro()] [not Right.isFromMacro()]
              [ Left.isIntegral() | Right.isIntegral() ]

//CallExpr
   [ Args[*]::AnyExpr[getTypeName() = 'char' | getTypeName() = 'char*' | getTypeName() = 'char[]' | getTypeName().ends-with(' char') | getTypeName().ends-with(' char*') | getTypeName().ends-with(' char[]')]
                     [$pos := getPositionInList()]
                     [ancestor::CallExpr[getLanguageType(getFormalParameter(getSemanticInfo(),$pos)).getTypeName().starts-with('wchar_t')]]
   ]

//BinaryExpr   [@Op = KTC_OPCODE_ASSIGN]
    [ Left::IdExpr [ isPointer() ]
       [ $ptTypeL := getPointedType() ] [not $ptTypeL.getPointedType().isPointer()]
       [ not $ptTypeL.isVolatile() ] [$0 := getName()]
    ]
   [ Right::AnyExpr/descendant::IdExpr [ not isPointer() ] [ isVolatile() ] [ $1 := getName() ]
   ]

//BinaryExpr   [@Op = KTC_OPCODE_ASSIGN]
    [ Left::IdExpr [ isPointer() ] [ $ptTypeL := getPointedType() ] [$ptTypeL2 := $ptTypeL.getPointedType()]
       [ isVolatile() | $ptTypeL.getPointedType().isVolatile() |  $ptTypeL2.getPointedType().isVolatile() ] [$0 := getName()]
    ]
    [ Right::AnyExpr/descendant::IdExpr [ isPointer() ] [ $ptTypeR := getPointedType() ] [ not $ptTypeR.isVolatile() ] [ not $ptTypeR.getPointedType().isVolatile() ] [$1 := getName()]
    ]

//FuncDef [not isCLanguage()]
             [  Declarator::PtrDeclarator/Declarator::FuncDeclarator
                [  Declarator::NameDeclarator/Name::OpFunc [@Op = KTC_OPCODE_NEW | @Op = KTC_OPCODE_NEW_ARRAY]]
                [  Throw::Null |
                   Throw::DenyThrowSpec/Expr::BoolLiteralExpr [@Value = KTC_BOOLVALUE_FALSE] |
                   Throw::DenyThrowSpec/Expr::BinaryExpr |
                   Throw::ExceptionSpec
                ]
             ]
          [FuncBody::FuncBody/Stmt::CompoundStmt
           [not  descendant::ThrowExpr/Expr::TypeConvExpr/Type::TypeName/Name::QualifiedName
                  [Qualifier::NameSpec [getName() = 'std']]
                  [Name::UnqualifiedName [getName() = 'bad_alloc']]
           ]
          ]

//MemberFunc [not isCLanguage()]
             [  Declarator::PtrDeclarator/Declarator::FuncDeclarator
                [  Declarator::NameDeclarator/Name::OpFunc [@Op = KTC_OPCODE_NEW | @Op = KTC_OPCODE_NEW_ARRAY]]
                [  Throw::Null |
                   Throw::DenyThrowSpec/Expr::BoolLiteralExpr [@Value = KTC_BOOLVALUE_FALSE] |
                   Throw::DenyThrowSpec/Expr::BinaryExpr |
                   Throw::ExceptionSpec
                ]
             ]
          [FuncBody::FuncBody/Stmt::CompoundStmt
           [not  descendant::ThrowExpr/Expr::TypeConvExpr/Type::TypeName/Name::QualifiedName
                  [Qualifier::NameSpec [getName() = 'std']]
                  [Name::UnqualifiedName [getName() = 'bad_alloc']]
           ]
          ]

//FuncDef [not isCLanguage()]
             [  Declarator::FuncDeclarator
                [  Declarator::NameDeclarator/Name::OpFunc [@Op = KTC_OPCODE_DELETE | @Op = KTC_OPCODE_DELETE_ARRAY]]
                [  Throw::Null |
                    Throw::DenyThrowSpec/Expr::BoolLiteralExpr [@Value = KTC_BOOLVALUE_FALSE] |
                   Throw::DenyThrowSpec/Expr::BinaryExpr |
                   Throw::ExceptionSpec/TypeIds[*]::TypeId
                ]
             ]

//MemberFunc [not isCLanguage()]
             [  Declarator::FuncDeclarator
                [  Declarator::NameDeclarator/Name::OpFunc [@Op = KTC_OPCODE_DELETE | @Op = KTC_OPCODE_DELETE_ARRAY]]
                [  Throw::Null |
                    Throw::DenyThrowSpec/Expr::BoolLiteralExpr [@Value = KTC_BOOLVALUE_FALSE] |
                   Throw::DenyThrowSpec/Expr::BinaryExpr |
                   Throw::ExceptionSpec/TypeIds[*]::TypeId
                ]
             ]

// FuncDef [not isCLanguage()] [Declarator::PtrDeclarator / Declarator::FuncDeclarator / Declarator::NameDeclarator / Name::OpFunc [@Op = KTC_OPCODE_NEW]
                                                                                                            [$0 := 'new']
                                                                                                            [$1 := 'delete']
        ]
        [not (parent::* / Decls[*]::FuncDef [Declarator::FuncDeclarator / Declarator::NameDeclarator / Name::OpFunc [@Op=KTC_OPCODE_DELETE] ])]

// MemberFunc [not isCLanguage()] [Declarator::PtrDeclarator / Declarator::FuncDeclarator / Declarator::NameDeclarator / Name::OpFunc[@Op = KTC_OPCODE_NEW]
                                                                                                                [$0:='new']
                                                                                                                [$1:='delete']
            ]
            [not (parent::*/MemberDecls[*]::MemberFunc[Declarator::FuncDeclarator/Declarator::NameDeclarator/Name::OpFunc[@Op=KTC_OPCODE_DELETE]])]

// MemberFunc [not isCLanguage()] [Declarator::FuncDeclarator / Declarator::NameDeclarator / Name::OpFunc [@Op = KTC_OPCODE_DELETE]
                                                                                    [$0 := 'delete']
                                                                                    [$1 := 'new']
            ]
            [not (parent::* / MemberDecls[*]::MemberFunc [Declarator::PtrDeclarator / Declarator::FuncDeclarator / Declarator::NameDeclarator / Name::OpFunc [@Op = KTC_OPCODE_NEW] ])]

// InitializedDeclarator
     [ Init::CopyInitializer/Expr::AnyExpr [ getUnderlyingType().getTypeName() != 'char' ]
                                           [ not isCharacterLiteral() ]
     ]
     [ getUnderlyingType().getTypeName() = 'char' ]

// UnaryExpr [ @Op = KTC_OPCODE_PREINC |
               @Op = KTC_OPCODE_PREDEC |
               @Op = KTC_OPCODE_POSTINC |
               @Op = KTC_OPCODE_POSTDEC ]
             [ Expr.getUnderlyingType().getTypeName() = 'char' ]
             [ not isOverloaded() ]

// LabeledStmt [ Label::CaseLabel [ Expr.getUnderlyingType().getTypeName() != 'char' ]
                                  [ not Expr.isCharacterLiteral() ]
               ]
               [ parent:: { LabeledStmt / parent:: } CompoundStmt
                                   / parent::SwitchStmt
                                              [ Cond.getUnderlyingType().getTypeName() = 'char' ] ]

// IfStmt [ isCLanguage() ]
          / Cond::* [ not isBoolean() ]
                    [ not getTypeName().contains-nocase('bool') ]

// DoStmt [ isCLanguage() ]
          / Cond::* [ not isBoolean() ]
                    [ not getTypeName().contains-nocase('bool') ]

// ForStmt [ isCLanguage() ]
           / Cond::* [ not isBoolean() ]
                     [ not getTypeName().contains-nocase('bool') ]

// WhileStmt [ isCLanguage() ]
             / Cond::* [ not isBoolean() ]
                       [ not getTypeName().contains-nocase('bool') ]

// CastExpr [ isCLanguage() ]
            [ Expr::AnyExpr
              [ getInitialDefinedType().isPointer() ]
              [ $0 := getTypeName() ]
            ]
            [ Type::TypeId
              [ not getInitialDefinedType().isPointer() ]
              [ not getInitialDefinedType().isIntegral() ]
              [ $1 := getTypeName() ]
            ]

// ForStmt [ isCLanguage() ]
           [ Init::Decl / Declarators[*]::AnyDeclarator [ $name := getName() ] ]
           [ Cond::AnyExpr [ not descendant::IdExpr [ getName() = $name ] ] ]

// IfStmt/Else::IfStmt
          [ Else::Null
          | Else::ExprStmt / Expr::Null
          | Else::CompoundStmt [ not containsComments() ]
                               [ not descendant::* [ name() != 'ExprStmt' | not Expr::Null ] ]
          ]

// EnumType [ Enumerators[0]::Enumerator [ Expr::* ]
                / following-sibling::Enumerator [ $0 := getName() ] [ Expr::* ] ]
            [ Enumerators[*]::Enumerator [ $1 := getName() ] [ Expr::Null ] ]

// FuncDeclarator [ isCLanguage() ]
                  [ Params[*]::Decl [ DeclSpecs::BuiltinType [ @Spec = KTC_BUILTINTYPE_VOID ] |
                                      DeclSpecs::TypeName [ getInitialDefinedType().getTypeName() = 'void' ] ]
                                    [ Declarators[*]::PtrDeclarator [ getName() = '' ] ]
                  ]
                  [ not ancestor::FuncDef ]

// AsmStmt  [ not comesFromMacro() ]
            [ ancestor::FuncBody / Stmt::CompoundStmt
              [ Stmts[*]::Decl
                | Stmts[*]::ExprStmt
            ] ]

// ParensExpr [ Expr::CastExpr ]
              [ not comesFromMacro() ]
              [ not parent::MemberExpr ]

// CastExpr [ Expr::ParensExpr
              [ not (Expr::BinaryExpr | Expr::ConditionalExpr) ]
              [ not comesFromMacro() ]
            ]

//IndexExpr [ Expr::ParensExpr [ not comesFromMacro() ]
              [ Expr::MemberExpr [ @Op = KTC_OPCODE_FIELD |
                                   @Op = KTC_OPCODE_FIELDREF ] ]
            ]

// SpecialCastExpr [ not isCLanguage() ]
                   [ Type::TypeId [ getInitialDefinedType().isIntegral() ] ]
                   [ Expr::AnyExpr [ isCValue() ]
                                   [ isFloatPoint() ]
                   ]

// SpecialCastExpr [ not isCLanguage() ]
                   [ Type::TypeId [ getInitialDefinedType().isFloatPoint() ] ]
                   [ Expr::AnyExpr [ isCValue() ]
                                   [ isIntegral() ]
                   ]

// ForStmt [ not isCLanguage() ]
           [ Cond::AnyExpr [ $type := getUnderlyingType() ]
                           [ not $type.isBoolean() ]
           ]
           [ $0 := $type.getTypeName() ]

// IfStmt [ not isCLanguage() ]
          [ Cond::AnyExpr [ $type := getUnderlyingType() ]
                          [ not $type.isBoolean() ]
          ]
          [ $0 := $type.getTypeName() ]

// WhileStmt [ not isCLanguage() ]
             [ Cond::AnyExpr [ $type := getUnderlyingType() ]
                             [ not $type.isBoolean() ]
             ]
             [ $0 := $type.getTypeName() ]

// TemplateDecl [ not isCLanguage() ]
                [ parent::TranslationUnit ]
                [ not getParent() | isGlobal() ]

// ExplicitInstantiation [ not isCLanguage() ]
                         [ parent::TranslationUnit ]
                         [ not getParent() | isGlobal() ]

// ThrowExpr [ not isCLanguage() ]
             [ ancestor::FuncDef [ isDestructor() ] | ancestor::MemberFunc [ isDestructor() ] ]
             [ not ancestor::TryStmt ]

// CallExpr [ not isCLanguage() ]
            [ Func::IdExpr [ getName() = 'terminate' ] ]
            [ Args::Null ]

// MemberDecl [ not isCLanguage() ]
              [ not DeclSpecs[*]::FuncSpec [ @Spec = KTC_FUNCSPECIFIER_VIRTUAL ] ]
              / Declarators[0]::AnyDeclarator [ isVirtual() ]

// MemberFunc [ not isCLanguage() ]
              [ isVirtual() ]
              [ not DeclSpecs[*]::FuncSpec [ @Spec = KTC_FUNCSPECIFIER_VIRTUAL ] ]

//ForStmt [ isCLanguage() ]
    [Cond::AnyExpr/descendant-or-self::AnyExpr [name()='BinaryExpr' | name()='UnaryExpr']
        [ $OpCode := getOperationCode() ]
        [ $OpCode = KTC_OPCODE_POSTINC | $OpCode = KTC_OPCODE_PREINC | $OpCode = KTC_OPCODE_POSTDEC |
          $OpCode = KTC_OPCODE_PREDEC | $OpCode = KTC_OPCODE_ASSIGN | $OpCode = KTC_OPCODE_MULASSIGN |
          $OpCode = KTC_OPCODE_DIVASSIGN | $OpCode = KTC_OPCODE_MODASSIGN | $OpCode = KTC_OPCODE_ADDASSIGN |
          $OpCode = KTC_OPCODE_SUBASSIGN | $OpCode = KTC_OPCODE_ASLASSIGN | $OpCode = KTC_OPCODE_ASRASSIGN |
          $OpCode = KTC_OPCODE_ANDASSIGN | $OpCode = KTC_OPCODE_XORASSIGN | $OpCode = KTC_OPCODE_ORASSIGN
        ]
    ]

//MemberExpr [ isCLanguage() ] [not parent::MemberExpr]
    [parent::{AnyExpr/parent::}ForStmt [not Expr::BinaryExpr [@Op=KTC_OPCODE_COMMA]]] [$name:=getName()] [not isBoolean()]
    [Name::Name [$isPtr:=isPointer()] [$sema:=getSemanticInfo()] ]
    [parent::{AnyExpr/parent::}AnyExpr/parent::ForStmt
        [Expr::AnyExpr/descendant-or-self::IdExpr [getSemanticInfo()!=$sema] [$this:=this()] ]
        [Expr::BinaryExpr/Left::IdExpr [this()=$this] | Expr::UnaryExpr/Expr::IdExpr [this()=$this] ]
    ]
    [parent::{AnyExpr/parent::}AnyExpr[$expr:=this()]/parent::ForStmt
        [Cond::AnyExpr/descendant-or-self::AnyExpr[this()=$expr]]
        [Stmt::{CompoundStmt/Stmts[*]::}AnyStmt
            [descendant-or-self::CallExpr
                [Args[*]::AnyExpr
                    [descendant-or-self::UnaryExpr [@Op=KTC_OPCODE_ADDRESS]
                        /descendant::MemberExpr [not parent::MemberExpr]
                        /Name::Name  [getSemanticInfo()=$sema]
                    ]
                |Args[*]::MemberExpr [not parent::MemberExpr]
                        /Name::Name [getSemanticInfo()=$sema] [$isPtr]
                ]
            ]
        ]
    ]
    [$0:=pretty()]
